/**
 * TrailStep MCP server.
 *
 * Uses the low-level `Server` from @modelcontextprotocol/sdk with explicit
 * `setRequestHandler` registrations (no zod, no high-level `McpServer`).
 * The `tools` registry below wires every generic MCP tool (`trst_run_workflow`,
 * `trst_watch`, `trst_answer`, `trst_resume`) with a plain JSON Schema
 * `inputSchema`; CallTool dispatches to the real tool implementations in
 * `tools/` and reports failures as `isError` tool results.
 *
 * Per-workflow tools (`.trailstep/mcp/trst_<id>.json`, regenerated by
 * `trailstep add` / `trailstep update`) are layered on top of the generic
 * registry: with the default `mcp.perWorkflowTools: true` each generated JSON
 * is listed as its own `trst_<id>` tool (params from the JSON `inputSchema`)
 * and dispatches to `runWorkflowTool` with the JSON's `workflowRef` preset;
 * with `mcp.perWorkflowTools: false` the server lists a single `trst_list`
 * discovery tool instead. The tool JSONs and config are re-read fresh on every
 * ListTools/CallTool request (no regeneration logic in the server).
 *
 * Resources: `trailstep://project` (resolved project directory as JSON) and
 * `trailstep://instructions` (generic + static snippet markdown; the project's
 * `.trailstep/mcp/instructions.md` is served when present).
 */
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListResourcesRequestSchema,
  ListToolsRequestSchema,
  ReadResourceRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";
import {
  loadPerWorkflowTools,
  type PerWorkflowToolDefinition,
  resolvePerWorkflowToolsEnabled,
} from "./tools/per_workflow.js";
import { runWorkflowTool } from "./tools/run_workflow.js";
import { trstAnswer } from "./tools/trst_answer.js";
import { trstList } from "./tools/trst_list.js";
import { trstResume } from "./tools/trst_resume.js";
import { trst_watch } from "./tools/trst_watch.js";

export interface McpToolDefinition {
  readonly name: string;
  readonly description: string;
  readonly inputSchema: {
    readonly type: "object";
    readonly properties: Record<string, unknown>;
    readonly required?: readonly string[];
  };
}

const projectDirProperty = {
  type: "string",
  description:
    "Optional project directory for run resolution. Defaults to the server project directory.",
} as const;

/** Tool registry: every MCP tool with its plain JSON Schema input contract. */
export const tools: readonly McpToolDefinition[] = [
  {
    name: "trst_run_workflow",
    description:
      'Start a TrailStep workflow run in the background and return immediately with {runId, runDir, status, workflow}. status is "started" only once the background run\'s directory actually materializes (bounded verification); when the run never starts (missing or refused CLI entry, spawn failure, or a run directory that never appears), status is "failed" with an "error" field and the result is reported as an isError tool result — never a false "started". When a per-workflow tool exists for the workflow you want (for example trst_delegate or trst_take-it-away), prefer it: it already knows the workflow reference and its input schema. Use this generic tool only when no per-workflow tool covers the workflow.',
    inputSchema: {
      type: "object",
      properties: {
        workflow: {
          type: "string",
          description: "Workflow reference (package id, bundle id, or workflow file path).",
        },
        input: {
          type: "object",
          additionalProperties: true,
          description: "Workflow input; must be a plain JSON object when provided.",
        },
        project: projectDirProperty,
      },
      required: ["workflow"],
    },
  },
  {
    name: "trst_watch",
    description:
      "Observe a TrailStep run's event stream since a byte-offset cursor (persisted across calls) with long-polling. The byte-offset cursor is persisted per run, so repeated calls continue where the last one stopped. An unknown or unreadable run id returns an error result instead of waiting. Use it together with trst_run_workflow to follow a run and trst_answer to answer a question the run is waiting on.",
    inputSchema: {
      type: "object",
      properties: {
        runId: {
          type: "string",
          description: "Run name or run id to observe.",
        },
        cursor: {
          type: "number",
          description:
            "Byte offset into events.jsonl to resume from; overrides the persisted cursor.",
        },
        verbosity: {
          type: "string",
          enum: ["brief", "normal", "full"],
          description:
            "Output verbosity; caps emitted lines at 50 (brief) / 100 (normal) / 200 (full).",
        },
        project: projectDirProperty,
      },
      required: ["runId"],
    },
  },
  {
    name: "trst_answer",
    description:
      "Answer a pending TrailStep wait by persisting the answer into the run's real wait answer file (optionally continuing the run).",
    inputSchema: {
      type: "object",
      properties: {
        runId: {
          type: "string",
          description: "Run name (under the runs root) or run directory path.",
        },
        waitId: {
          type: "string",
          description: "Id of the pending wait to answer.",
        },
        answer: {
          type: "object",
          additionalProperties: true,
          description: "Answer payload persisted verbatim into the wait answer file (JSON object).",
        },
        branchId: {
          type: "string",
          description: "Disambiguates same-id waits pending on parallel branches.",
        },
        continueAfterAnswer: {
          type: "boolean",
          description: "After persisting the answer, run the same continue path trst_resume uses.",
        },
        project: projectDirProperty,
      },
      required: ["runId", "waitId", "answer"],
    },
  },
  {
    name: "trst_resume",
    description:
      "Continue a waiting TrailStep run via the real `trailstep continue` path and report the continue status.",
    inputSchema: {
      type: "object",
      properties: {
        runId: {
          type: "string",
          description: "Run name (under the runs root) or run directory path.",
        },
        project: projectDirProperty,
      },
      required: ["runId"],
    },
  },
];

export interface CreateServerOptions {
  /** Project directory the server operates against (already absolute). */
  readonly projectDir?: string;
  /**
   * Home directory anchoring the global config/tool JSON layers. Defaults to
   * the real home directory; tests inject a tmp dir for isolation.
   */
  readonly homeDir?: string;
}

const SERVER_INFO = { name: "trailstep-mcp", version: "0.1.0" } as const;

/**
 * Server instructions sent on initialize: the run -> watch -> answer -> resume
 * loop, with a pointer to the `trailstep://instructions` resource that carries
 * the same mapping in detail.
 */
export const SERVER_INSTRUCTIONS =
  "TrailStep MCP server: start a workflow with trst_run_workflow (or a per-workflow trst_* tool), follow it with trst_watch, answer a question the run is waiting on with trst_answer, and continue the run with trst_resume. The trailstep://instructions resource describes this run -> watch -> answer -> resume loop.";

export const PROJECT_RESOURCE_URI = "trailstep://project";
export const INSTRUCTIONS_RESOURCE_URI = "trailstep://instructions";

/**
 * `trst_list` tool definition (list mode only):
 * `mcp.perWorkflowTools: false` lists this instead of the per-workflow tools.
 */
export const TRST_LIST_TOOL: McpToolDefinition = {
  name: "trst_list",
  description:
    "List the available per-workflow TrailStep tools ({name, description}) from the generated .trailstep/mcp tool JSONs.",
  inputSchema: {
    type: "object",
    properties: {},
  },
};

/** Names owned by the generic registry; per-workflow JSONs cannot shadow them. */
const RESERVED_TOOL_NAMES = new Set<string>([
  ...tools.map((tool) => tool.name),
  TRST_LIST_TOOL.name,
]);

/**
 * Tools exposed on ListTools for the current mode: generic registry plus
 * either the per-workflow tools (default) or `trst_list` (list mode). Tool
 * JSONs and the mode flag are read fresh per call.
 */
export function listedToolDefinitions(
  projectDir: string,
  homeDir?: string,
): readonly McpToolDefinition[] {
  const options = {
    projectDir,
    ...(homeDir === undefined ? {} : { homeDir }),
  };
  const perWorkflowTools = loadPerWorkflowTools(options).filter(
    (tool) => !RESERVED_TOOL_NAMES.has(tool.name),
  );
  if (resolvePerWorkflowToolsEnabled(options)) {
    return [...tools, ...perWorkflowTools];
  }
  return [...tools, TRST_LIST_TOOL];
}

/**
 * Fallback instructions content: generic usage guidance plus the static
 * tool-mapping snippet (mirrors `.trailstep/mcp/instructions.md`).
 */
export const INSTRUCTIONS_FALLBACK = `# TrailStep MCP Instructions

## Embedded generic snippet

Usage of \`trst_watch\`, \`trst_answer\`, and \`trst_resume\` for observing and interacting with a running workflow.

## Embedded static snippet

\`\`\`json
{
  "watch": "trst_watch",
  "answer": "trst_answer",
  "resume": "trst_resume"
}
\`\`\`
`;

/** Build the low-level MCP server with ListTools/CallTool/ListResources/ReadResource handlers. */
export function createServer(options: CreateServerOptions = {}): Server {
  const projectDir = options.projectDir ?? path.resolve(".");
  const homeDir = options.homeDir;

  const server = new Server(SERVER_INFO, {
    capabilities: {
      tools: {},
      resources: {},
    },
    instructions: SERVER_INSTRUCTIONS,
  });

  server.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: listedToolDefinitions(projectDir, homeDir).map((tool) => ({
      name: tool.name,
      description: tool.description,
      inputSchema: {
        type: "object" as const,
        properties: tool.inputSchema.properties,
        ...(tool.inputSchema.required ? { required: [...tool.inputSchema.required] } : {}),
      },
    })),
  }));

  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const name = request.params.name;
    const args = (request.params.arguments ?? {}) as Record<string, unknown>;
    try {
      const result = await dispatchTool(name, args, projectDir, homeDir);
      return {
        content: [{ type: "text" as const, text: JSON.stringify(result) }],
      };
    } catch (error) {
      if (error instanceof ToolReportError) {
        // Structured failure payload (e.g. run_workflow status "failed"):
        // an isError result whose text is the JSON payload, so callers can
        // parse {runId, runDir, status, error} while still seeing the failure.
        return {
          content: [{ type: "text" as const, text: JSON.stringify(error.payload) }],
          isError: true,
        };
      }
      return toolError(`${name}: ${error instanceof Error ? error.message : String(error)}`);
    }
  });

  server.setRequestHandler(ListResourcesRequestSchema, async () => ({
    resources: [
      {
        uri: PROJECT_RESOURCE_URI,
        name: "TrailStep project",
        description: "The project directory this MCP server operates against.",
        mimeType: "application/json",
      },
      {
        uri: INSTRUCTIONS_RESOURCE_URI,
        name: "TrailStep MCP instructions",
        description: "Generic usage instructions plus the static tool-mapping snippet.",
        mimeType: "text/markdown",
      },
    ],
  }));

  server.setRequestHandler(ReadResourceRequestSchema, async (request) => {
    const uri = request.params.uri;
    if (uri === PROJECT_RESOURCE_URI) {
      return {
        contents: [
          {
            uri,
            mimeType: "application/json",
            text: JSON.stringify({ projectDir }),
          },
        ],
      };
    }
    if (uri === INSTRUCTIONS_RESOURCE_URI) {
      return {
        contents: [
          {
            uri,
            mimeType: "text/markdown",
            text: readInstructions(projectDir),
          },
        ],
      };
    }
    throw new Error(`Unknown resource: ${uri}`);
  });

  return server;
}

/** Connect the server over stdio (foreground; caller owns the process lifetime). */
export async function serveStdio(options: CreateServerOptions = {}): Promise<Server> {
  const server = createServer(options);
  await server.connect(new StdioServerTransport());
  return server;
}

/**
 * Dispatch completed but the tool reported an operational failure with a
 * structured JSON payload (run_workflow `status: "failed"`). Rethrown through
 * dispatch so the CallTool handler can emit an `isError` tool result whose
 * text is the payload — consistent with the server's convention that failures
 * are `isError` results and a started run is plain content.
 */
class ToolReportError extends Error {
  readonly payload: unknown;

  constructor(payload: unknown) {
    super("tool reported a failed result");
    this.payload = payload;
  }
}

function toolError(text: string): {
  content: { type: "text"; text: string }[];
  isError: true;
} {
  return {
    content: [{ type: "text" as const, text }],
    isError: true,
  };
}

/**
 * Dispatch a CallTool request to the real tool implementation: the generic
 * registry first, then `trst_list`, then the per-workflow tools (resolved
 * fresh from the layered tool JSONs, with the JSON's `workflowRef` preset so
 * callers cannot redirect the run). Throws on malformed arguments and unknown
 * tools; the CallTool handler converts throws into `isError` tool results.
 * A run_workflow dispatch that reports `status: "failed"` throws a
 * `ToolReportError` so the structured JSON payload is surfaced as an
 * `isError` result too (a successfully started run stays plain content).
 */
async function dispatchTool(
  name: string,
  args: Record<string, unknown>,
  projectDir: string,
  homeDir: string | undefined,
): Promise<unknown> {
  const cwd =
    typeof args.project === "string" && args.project.trim() !== ""
      ? path.resolve(args.project)
      : projectDir;

  if (!tools.some((candidate) => candidate.name === name) && name !== TRST_LIST_TOOL.name) {
    const perWorkflowTool = findPerWorkflowTool(name, projectDir, homeDir);
    if (perWorkflowTool !== undefined) {
      return await dispatchPerWorkflowTool(perWorkflowTool, args, cwd);
    }
    throw new Error(`Unknown tool: ${name}`);
  }

  switch (name) {
    case "trst_run_workflow": {
      const workflow = readOptionalString(args.workflow) ?? readOptionalString(args.workflowRef);
      if (workflow === undefined) {
        throw new Error("`workflow` must be a non-empty string.");
      }
      const result = await runWorkflowTool({
        workflowRef: workflow,
        ...(args.input === undefined ? {} : { input: args.input }),
        cwd,
      });
      const payload = { ...result, workflow };
      if (result.status === "failed") {
        throw new ToolReportError(payload);
      }
      return payload;
    }
    case "trst_watch": {
      return await trst_watch(
        {
          ...(readOptionalString(args.runId) === undefined
            ? {}
            : { runId: readOptionalString(args.runId) }),
          ...(typeof args.cursor === "number" ? { cursor: args.cursor } : {}),
          ...(args.verbosity === "brief" || args.verbosity === "normal" || args.verbosity === "full"
            ? { verbosity: args.verbosity }
            : {}),
        },
        { cwd },
      );
    }
    case "trst_answer": {
      const runId = readOptionalString(args.runId);
      const waitId = readOptionalString(args.waitId);
      if (runId === undefined || waitId === undefined) {
        throw new Error("`runId` and `waitId` must be non-empty strings.");
      }
      if (typeof args.answer !== "object" || args.answer === null || Array.isArray(args.answer)) {
        throw new Error("`answer` must be a JSON object.");
      }
      return await trstAnswer({
        runId,
        waitId,
        answer: args.answer as Record<string, unknown>,
        ...(readOptionalString(args.branchId) === undefined
          ? {}
          : { branchId: readOptionalString(args.branchId) }),
        ...(args.continueAfterAnswer === true ? { continueAfterAnswer: true } : {}),
        cwd,
      });
    }
    case "trst_resume": {
      const runId = readOptionalString(args.runId);
      if (runId === undefined) {
        throw new Error("`runId` must be a non-empty string.");
      }
      return await trstResume({ runId, cwd });
    }
    case "trst_list": {
      return await trstList({
        projectDir: cwd,
        ...(homeDir === undefined ? {} : { homeDir }),
      });
    }
    default:
      throw new Error(`Unknown tool: ${name}`);
  }
}

/** Resolves one per-workflow tool definition by name from a fresh tool JSON load. */
function findPerWorkflowTool(
  name: string,
  projectDir: string,
  homeDir: string | undefined,
): PerWorkflowToolDefinition | undefined {
  const options = {
    projectDir,
    ...(homeDir === undefined ? {} : { homeDir }),
  };
  return loadPerWorkflowTools(options).find(
    (tool) => tool.name === name && !RESERVED_TOOL_NAMES.has(tool.name),
  );
}

/**
 * Dispatches a per-workflow tool to `runWorkflowTool` with the JSON's
 * `workflowRef` preset; the call's arguments are the workflow input.
 */
async function dispatchPerWorkflowTool(
  tool: PerWorkflowToolDefinition,
  args: Record<string, unknown>,
  cwd: string,
): Promise<unknown> {
  const result = await runWorkflowTool({
    workflowRef: tool.workflowRef,
    input: args,
    cwd,
  });
  const payload = { ...result, workflow: tool.workflowRef, tool: tool.name };
  if (result.status === "failed") {
    throw new ToolReportError(payload);
  }
  return payload;
}

function readOptionalString(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() !== "" ? value.trim() : undefined;
}

/**
 * Instructions resource content: the project's `.trailstep/mcp/instructions.md`
 * when present, else the embedded generic + static snippet.
 */
function readInstructions(projectDir: string): string {
  const projectInstructions = path.join(projectDir, ".trailstep", "mcp", "instructions.md");
  if (existsSync(projectInstructions)) {
    try {
      return readFileSync(projectInstructions, "utf8");
    } catch {
      // Fall through to the embedded snippet on any read failure.
    }
  }
  return INSTRUCTIONS_FALLBACK;
}
